bool linear_search(int a[], int n, int x){
    for(int i = 0; i < n; i++)
        if(a[i] == x) return true;
    return false;
}

int firstPos(int a[], int n, int x){
    for(int i = 0; i < n; i++)
        if(a[i] == x) return i;
    return -1;   // khong tim thay
}
// a={6,1,2,4,3,10,9,3,8,6}, x=3 -> vi tri 4

int count(int a[], int n, int x){
    int res = 0;
    for(int i = 0; i < n; i++)
        if(a[i] == x) ++res;
    return res;
}
// a={6,1,2,4,3,10,9,3,8,6}, x=3 -> res = 2
